INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十四", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b8cc8594d63007caf3bc997ace00c8ade1071c2e/content/books/zizhi-tongjian/vol-292/year-0954/part-02/sources/library/jiuwudaishi-114-august-li-yanchong/source.txt", "note": "《旧五代史》卷一百十四，段落 jiu-wudaishi-205deb4a7860-p002713；EPUB电子本，纸本及异文待核", "id": "e72dc72e-5dda-5d54-b3ef-ae094ea0ecb5"}, {"title": "旧五代史·卷一百十四", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b8cc8594d63007caf3bc997ace00c8ade1071c2e/content/books/zizhi-tongjian/vol-292/year-0954/part-02/sources/library/jiuwudaishi-114-july-954/source.txt", "note": "《旧五代史》卷一百十四，段落 jiu-wudaishi-205deb4a7860-p002712；EPUB电子本，纸本及异文待核", "id": "30b200ac-2342-52cc-9cf5-8de37374a443"}, {"title": "宋史·巻二百五十四", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b8cc8594d63007caf3bc997ace00c8ade1071c2e/content/books/zizhi-tongjian/vol-292/year-0954/part-02/sources/library/songshi-254-yao-yuanfu-retreat/source.txt", "note": "《宋史》巻二百五十四，段落 songshi-9c6e46fee832-p057514；EPUB电子本，纸本及异文待核", "id": "e1a31650-ebae-59e9-8219-2e0bb8866a6f"}, {"title": "资治通鉴·后周纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b8cc8594d63007caf3bc997ace00c8ade1071c2e/content/books/zizhi-tongjian/vol-292/year-0954/part-02/sources/library/tongjian-292-954-summer-autumn/source.txt", "note": "《资治通鉴》后周纪三，段落 zizhi-tongjian-a63549944a71-p003466；电子底本待考，分段待核", "id": "a66d5cae-8694-531b-89b0-6d7bdf64fef7"}, {"title": "资治通鉴·后周纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2045d769bf64a5bf30604e638acd5ac322c1f6df/content/books/zizhi-tongjian/vol-292/year-0954/part-01/sources/library/tongjian-292-954-may-siege/source.txt", "note": "《资治通鉴》后周纪三，段落 zizhi-tongjian-a63549944a71-p003465；电子底本待考，分段待核", "id": "b06aa302-d0cb-5049-817e-af8209d7b81f"}, {"title": "新五代史·卷七十", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2045d769bf64a5bf30604e638acd5ac322c1f6df/content/books/zizhi-tongjian/vol-292/year-0954/part-01/sources/library/xinwudaishi-70-sang-gui-zheng/source.txt", "note": "《新五代史》卷七十，段落 xin-wudaishi-b08f244b9241-p003453；EPUB电子本，纸本及异文待核", "id": "b9c6824e-61a1-5cb2-a3c0-57f770c04583"}, {"title": "旧五代史·卷一百十四", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2045d769bf64a5bf30604e638acd5ac322c1f6df/content/books/zizhi-tongjian/vol-292/year-0954/part-01/sources/library/jiuwudaishi-114-siege-labor-954/source.txt", "note": "《旧五代史》卷一百十四，段落 jiu-wudaishi-205deb4a7860-p002711；EPUB电子本，纸本及异文待核", "id": "8c039b5e-2944-563b-9e4e-22b7ac1e7143"}, {"title": "新五代史·卷12·周本纪第十二·柴荣即位", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/3ba4c15f89bc0e4a416ae35be0615a8c443b7f49/content/books/zizhi-tongjian/vol-291/year-0954/part-01/sources/library/xinwudaishi-12-chairong-accession/source.txt", "note": "《新五代史》卷12·周本纪第十二·柴荣即位，段落 xin-wudaishi-b08f244b9241-p000376；已核上下文及传主，纸本及异文待核。", "id": "e8e8d8ba-d759-5bf8-896c-ca674bd3a93d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "王得中", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "上党人，北汉枢密直学士。951年九月受刘崇派遣出使契丹，祝贺新君即位，并请求援兵进攻晋州。生卒年未载。", "biography": null, "status": "draft", "id": "24fc3a64-54f4-5587-8e68-cf8c2b329c89"}, {"name": "桑珪", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "代州将领。954年五月与解文遇杀死已降后周的郑处谦，诬称郑暗通契丹。《新五代史》也记桑珪杀郑处谦并以城降周。生卒年本段未载，后续行动另随编年录入。", "biography": null, "status": "draft", "id": "0d305981-af3a-59ad-ae51-cf8159ae3565"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "药元福", "aliases": ["藥元福"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州晋阳人，早年侍奉王檀及后唐，曾任深州刺史。945年任后晋马军右厢副排阵使，在白团卫村被围时主张逆风急击，与符彦卿、张彦泽、皇甫遇领骑兵出战。《宋史》还记他战后任威州刺史。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "9bbd6971-3005-5379-8428-512e90ae87d6"}, {"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "高锡", "aliases": ["高錫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "河中人，后周河南府推官。954年柴荣围晋阳返朝后，上书劝他选择适任官员、让宰相和地方官分掌事务，不要事事亲决，柴荣未采纳。生卒年未载。", "biography": null, "status": "draft", "id": "4d3cfc2d-205d-5763-99a0-694126ae66de"}, {"name": "刘承钧", "aliases": ["劉承鈞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘崇的次子。951年父亲在晋阳称帝时，任侍卫亲军都指挥使、太原尹。《旧五代史》也记他是刘崇之子并任两职。生卒年本批未录。", "biography": null, "status": "draft", "id": "3f4681a7-ca79-5d5d-a5c2-53bef1936681"}, {"name": "申师厚", "aliases": ["申師厚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王峻的故交，曾为兖州牙将，失去职务后生活困顿。951年经王峻推荐任河西节度使，《旧五代史》还记任职前先授左卫将军。生卒年未载。", "biography": null, "status": "draft", "id": "726c5795-d4be-50c7-b995-7c1e7267c2bf"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "范质", "aliases": ["范質", "範質"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "宗城人，后晋主客员外郎。944年六月戊辰任翰林学士。后续仕宦随编年主线补录。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "abe2c0af-4bf3-551b-83c9-f355ba085a0e"}, {"name": "景范", "aliases": ["景範"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "长山人，后周枢密直学士、工部侍郎。954年七月癸巳获任中书侍郎、同平章事并判三司。《旧五代史》同记任命，名字作景範。生卒年未载。", "biography": null, "status": "draft", "id": "c6d39d95-b63f-5ce0-9263-66db615f1bc9"}, {"name": "郑仁诲", "aliases": ["鄭仁誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，后周内客省使、恩州团练使。952年三月任枢密副使，新旧五代史同日记载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "f7eb66ac-1c5c-5720-aa2e-9256e75c2b71"}, {"name": "魏仁浦", "aliases": ["魏仁溥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字道济，卫州汲人。后晋末任枢密院小吏，随众被迁往契丹后逃归。947年在巩县迎见刘知远，因熟知军队人数与旧制受到郭威信任。生卒年尚未录入。", "biography": null, "status": "draft", "id": "c2e87754-6e6a-56db-b3e1-45835b2bff92"}, {"name": "窦贞固", "aliases": ["竇貞固"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：窦贞固，原节度推官、获任者。", "biography": null, "status": "draft", "id": "628caf07-3ba2-5bc4-8630-598667f5bdd0"}, {"name": "向训", "aliases": ["向訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年与陈思让参与虒亭战事，《旧五代史》称监军，《宋史》称都监。生卒年及后续改名尚未据本次引文录入。", "biography": null, "status": "draft", "id": "1d29bcb9-6ec9-5369-89ff-ea67f0460acc"}, {"name": "李彦崇", "aliases": ["李彥崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "前泽州刺史。954年高平之战时奉命守江猪岭，截断北汉退路，却在听闻周军南逃后退兵，使刘崇得以经该路逃归。八月己酉因失职降任率府副率。生卒年未载。", "biography": null, "status": "draft", "id": "9df02e3a-11c1-5931-9ba2-202799ccb756"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
